B.Oq=new A.cs("00","\u0428\u0443\u0442","\u041d\u0430\u0447\u043d\u0438\u0442\u0435, \u043d\u0435 \u0437\u043d\u0430\u044f \u0432\u0441\u0435\u0433\u043e","\u0421\u0435\u0433\u043e\u0434\u043d\u044f \u043c\u043e\u0436\u043d\u043e \u043f\u043e\u0437\u0432\u043e\u043b\u0438\u0442\u044c \u0441\u0435\u0431\u0435 \u0448\u0430\u0433, \u043a \u043a\u043e\u0442\u043e\u0440\u043e\u043c\u0443 \u0432\u044b \u043d\u0435 \u0433\u043e\u0442\u043e\u0432\u044b \u043f\u043e\u043b\u043d\u043e\u0441\u0442\u044c\u044e \u2014 \u0438 \u044d\u0442\u043e \u0435\u0434\u0438\u043d\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0439 \u0441\u043f\u043e\u0441\u043e\u0431 \u0432\u043e\u043e\u0431\u0449\u0435 \u0435\u0433\u043e \u0441\u0434\u0435\u043b\u0430\u0442\u044c. \u0413\u043e\u0442\u043e\u0432\u043d\u043e\u0441\u0442\u044c \u043f\u0440\u0438\u0445\u043e\u0434\u0438\u0442 \u043f\u043e \u0434\u043e\u0440\u043e\u0433\u0435, \u0430 \u043d\u0435 \u0434\u043e \u043d\u0435\u0451. \u041d\u0435 \u0436\u0434\u0438\u0442\u0435, \u043f\u043e\u043a\u0430 \u0441\u043b\u043e\u0436\u0438\u0442\u0441\u044f \u0432\u0435\u0441\u044c \u043f\u043b\u0430\u043d: \u0443 \u0428\u0443\u0442\u0430 \u0437\u0430 \u0441\u043f\u0438\u043d\u043e\u0439 \u043e\u0434\u0438\u043d \u0443\u0437\u0435\u043b\u043e\u043a, \u0438 \u0435\u0433\u043e \u0445\u0432\u0430\u0442\u0430\u0435\u0442. \u0414\u0435\u043d\u044c \u0434\u043b\u044f \u043f\u0435\u0440\u0432\u043e\u0433\u043e \u0434\u0432\u0438\u0436\u0435\u043d\u0438\u044f, \u0434\u043b\u044f \u043f\u0438\u0441\u044c\u043c\u0430, \u043a\u043e\u0442\u043e\u0440\u043e\u0435 \u0434\u0430\u0432\u043d\u043e \u043d\u0435 \u043d\u0430\u043f\u0438\u0441\u0430\u043d\u043e, \u0434\u043b\u044f \u0440\u0430\u0437\u0433\u043e\u0432\u043e\u0440\u0430, \u043a\u043e\u0442\u043e\u0440\u044b\u0439 \u043e\u0442\u043a\u043b\u0430\u0434\u044b\u0432\u0430\u0435\u0442\u0441\u044f \u0438\u0437 \u0441\u0442\u0440\u0430\u0445\u0430 \u0432\u044b\u0433\u043b\u044f\u0434\u0435\u0442\u044c \u043d\u0435\u043b\u043e\u0432\u043a\u043e.","\u0428\u0430\u0433, \u043a\u043e\u0442\u043e\u0440\u044b\u0439 \u0432\u044b \u0432\u0441\u0451-\u0442\u0430\u043a\u0438 \u043d\u0435 \u0434\u0435\u043b\u0430\u0435\u0442\u0435. \u041d\u0435 \u043f\u043e\u0442\u043e\u043c\u0443, \u0447\u0442\u043e \u0440\u0430\u043d\u043e, \u2014 \u0430 \u043f\u043e\u0442\u043e\u043c\u0443, \u0447\u0442\u043e \u0436\u0434\u0451\u0442\u0435 \u0433\u0430\u0440\u0430\u043d\u0442\u0438\u0438, \u043a\u043e\u0442\u043e\u0440\u043e\u0439 \u043d\u0435 \u0431\u0443\u0434\u0435\u0442. \u041b\u0438\u0431\u043e \u043d\u0430\u043e\u0431\u043e\u0440\u043e\u0442: \u043f\u0440\u044b\u0436\u043e\u043a \u0443\u0436\u0435 \u0441\u0434\u0435\u043b\u0430\u043d, \u043d\u043e \u0431\u0435\u0437 \u0443\u0437\u0435\u043b\u043a\u0430 \u0437\u0430 \u0441\u043f\u0438\u043d\u043e\u0439, \u0438 \u0442\u0435\u043f\u0435\u0440\u044c \u043f\u0440\u0438\u0445\u043e\u0434\u0438\u0442\u0441\u044f \u0437\u0430\u043d\u0438\u043c\u0430\u0442\u044c \u0443 \u0432\u0441\u0435\u0445 \u043f\u043e\u0434\u0440\u044f\u0434.")
B.OG=new A.cs("01","\u041c\u0430\u0433","\u0412\u0441\u0451 \u043d\u0443\u0436\u043d\u043e\u0435 \u0443\u0436\u0435 \u043f\u0440\u0438 \u0432\u0430\u0441","\u041d\u0430 \u0441\u0442\u043e\u043b\u0435 \u043f\u0435\u0440\u0435\u0434 \u041c\u0430\u0433\u043e\u043c \u043b\u0435\u0436\u0430\u0442 \u0447\u0435\u0442\u044b\u0440\u0435 \u043f\u0440\u0435\u0434\u043c\u0435\u0442\u0430, \u0438 \u043e\u043d \u043d\u0435 \u0438\u0449\u0435\u0442 \u043f\u044f\u0442\u044b\u0439. \u0421\u0435\u0433\u043e\u0434\u043d\u044f\u0448\u043d\u044f\u044f \u0437\u0430\u0434\u0430\u0447\u0430 \u0440\u0435\u0448\u0430\u0435\u0442\u0441\u044f \u0442\u0435\u043c, \u0447\u0442\u043e \u0443 \u0432\u0430\u0441 \u0443\u0436\u0435 \u0435\u0441\u0442\u044c \u2014 \u0437\u043d\u0430\u043d\u0438\u0435\u043c, \u0447\u0435\u043b\u043e\u0432\u0435\u043a\u043e\u043c, \u0438\u043d\u0441\u0442\u0440\u0443\u043c\u0435\u043d\u0442\u043e\u043c, \u043e \u043a\u043e\u0442\u043e\u0440\u043e\u043c \u0432\u044b \u043f\u043e\u0447\u0435\u043c\u0443-\u0442\u043e \u043d\u0435 \u043f\u043e\u0434\u0443\u043c\u0430\u043b\u0438. \u041f\u0440\u0435\u0436\u0434\u0435 \u0447\u0435\u043c \u0438\u0441\u043a\u0430\u0442\u044c \u043d\u0435\u0434\u043e\u0441\u0442\u0430\u044e\u0449\u0435\u0435, \u043f\u0435\u0440\u0435\u0441\u0447\u0438\u0442\u0430\u0439\u0442\u0435 \u0438\u043c\u0435\u044e\u0449\u0435\u0435\u0441\u044f. \u0414\u0435\u043d\u044c \u0445\u043e\u0440\u043e\u0448 \u0434\u043b\u044f \u0434\u0435\u043b\u0430, \u0433\u0434\u0435 \u043d\u0443\u0436\u043d\u043e \u0441\u043e\u0431\u0440\u0430\u0442\u044c \u0440\u0430\u0437\u043d\u043e\u0435 \u0432\u043c\u0435\u0441\u0442\u0435, \u0438 \u043f\u043b\u043e\u0445 \u0434\u043b\u044f \u043f\u043e\u043a\u0443\u043f\u043a\u0438 \u043d\u043e\u0432\u043e\u0433\u043e.","\u0412\u0441\u0451 \u043d\u0443\u0436\u043d\u043e\u0435 \u043f\u0440\u0438 \u0432\u0430\u0441, \u0438 \u0432\u044b \u044d\u0442\u0438\u043c \u043d\u0435 \u043f\u043e\u043b\u044c\u0437\u0443\u0435\u0442\u0435\u0441\u044c. \u0418\u0449\u0435\u0442\u0435 \u043f\u044f\u0442\u044b\u0439 \u043f\u0440\u0435\u0434\u043c\u0435\u0442, \u043a\u043e\u0433\u0434\u0430 \u0447\u0435\u0442\u044b\u0440\u0451\u0445 \u0434\u043e\u0441\u0442\u0430\u0442\u043e\u0447\u043d\u043e, \u2014 \u0438\u043b\u0438 \u043f\u043e\u043a\u0430\u0437\u044b\u0432\u0430\u0435\u0442\u0435 \u0444\u043e\u043a\u0443\u0441 \u0432\u043c\u0435\u0441\u0442\u043e \u0442\u043e\u0433\u043e, \u0447\u0442\u043e\u0431\u044b \u0441\u0434\u0435\u043b\u0430\u0442\u044c \u0434\u0435\u043b\u043e. \u0421\u0435\u0433\u043e\u0434\u043d\u044f \u043f\u0440\u043e\u0432\u0435\u0440\u044c\u0442\u0435, \u043d\u0435 \u0442\u0440\u0430\u0442\u0438\u0442\u0435 \u043b\u0438 \u0432\u044b \u0441\u0438\u043b\u044b \u043d\u0430 \u0442\u043e, \u0447\u0442\u043e\u0431\u044b \u0432\u044b\u0433\u043b\u044f\u0434\u0435\u0442\u044c \u0441\u043f\u043e\u0441\u043e\u0431\u043d\u044b\u043c.")
B.Ow=new A.cs("02","\u0416\u0440\u0438\u0446\u0430","\u041e\u0442\u0432\u0435\u0442 \u043f\u0440\u0438\u0434\u0451\u0442 \u0432 \u0442\u0438\u0448\u0438\u043d\u0435","\u041d\u0435 \u0442\u043e\u0440\u043e\u043f\u0438\u0442\u0435\u0441\u044c \u0441 \u0440\u0435\u0448\u0435\u043d\u0438\u0435\u043c: \u0442\u043e, \u0447\u0442\u043e \u043a\u0430\u0436\u0435\u0442\u0441\u044f \u043d\u0435\u044f\u0441\u043d\u044b\u043c, \u043f\u0440\u043e\u044f\u0441\u043d\u044f\u0435\u0442\u0441\u044f \u0441\u0430\u043c\u043e, \u0435\u0441\u043b\u0438 \u043d\u0435 \u0442\u043e\u0440\u043c\u043e\u0448\u0438\u0442\u044c. \u0416\u0440\u0438\u0446\u0430 \u0441\u0438\u0434\u0438\u0442 \u043c\u0435\u0436\u0434\u0443 \u0434\u0432\u0443\u0445 \u0441\u0442\u043e\u043b\u043f\u043e\u0432 \u0438 \u043c\u043e\u043b\u0447\u0438\u0442 \u2014 \u043d\u0435 \u043f\u043e\u0442\u043e\u043c\u0443 \u0447\u0442\u043e \u043d\u0435 \u0437\u043d\u0430\u0435\u0442, \u0430 \u043f\u043e\u0442\u043e\u043c\u0443 \u0447\u0442\u043e \u0441\u0440\u043e\u043a \u043d\u0435 \u043f\u0440\u0438\u0448\u0451\u043b. \u0421\u0435\u0433\u043e\u0434\u043d\u044f \u0432\u044b\u0433\u043e\u0434\u043d\u0435\u0435 \u0441\u043b\u0443\u0448\u0430\u0442\u044c, \u0447\u0435\u043c \u043e\u0431\u044a\u044f\u0441\u043d\u044f\u0442\u044c. \u041e\u0431\u0440\u0430\u0442\u0438\u0442\u0435 \u0432\u043d\u0438\u043c\u0430\u043d\u0438\u0435 \u043d\u0430 \u0442\u043e, \u0447\u0442\u043e \u0437\u0430\u043c\u0435\u0442\u0438\u043b\u0438 \u043a\u0440\u0430\u0435\u043c \u0433\u043b\u0430\u0437\u0430 \u0438 \u043e\u0442\u043c\u0430\u0445\u043d\u0443\u043b\u0438\u0441\u044c: \u0438\u043c\u0435\u043d\u043d\u043e \u0442\u0430\u043c \u0438 \u043b\u0435\u0436\u0438\u0442 \u043f\u043e\u0434\u0441\u043a\u0430\u0437\u043a\u0430.","\u0422\u0438\u0448\u0438\u043d\u0430, \u0432 \u043a\u043e\u0442\u043e\u0440\u043e\u0439 \u0443\u0436\u0435 \u043d\u0438\u043a\u0442\u043e \u043d\u0435 \u043e\u0442\u0432\u0435\u0447\u0430\u0435\u0442. \u0416\u0434\u0430\u0442\u044c \u0434\u0430\u043b\u044c\u0448\u0435 \u2014 \u043d\u0435 \u0442\u0435\u0440\u043f\u0435\u043d\u0438\u0435, \u0430 \u0441\u043f\u043e\u0441\u043e\u0431 \u043d\u0435 \u0440\u0435\u0448\u0430\u0442\u044c. \u041b\u0438\u0431\u043e \u0432\u044b \u0447\u0442\u043e-\u0442\u043e \u0437\u043d\u0430\u0435\u0442\u0435 \u0438 \u043c\u043e\u043b\u0447\u0438\u0442\u0435 \u043e\u0431 \u044d\u0442\u043e\u043c \u0442\u0430\u043a \u0434\u043e\u043b\u0433\u043e, \u0447\u0442\u043e \u043c\u043e\u043b\u0447\u0430\u043d\u0438\u0435 \u0441\u0430\u043c\u043e \u0441\u0442\u0430\u043b\u043e \u043f\u0440\u043e\u0431\u043b\u0435\u043c\u043e\u0439.")
B.On=new A.cs("03","\u0418\u043c\u043f\u0435\u0440\u0430\u0442\u0440\u0438\u0446\u0430","\u0414\u0430\u0439\u0442\u0435 \u0432\u044b\u0440\u0430\u0441\u0442\u0438","\u0414\u0435\u043d\u044c \u0434\u043b\u044f \u0437\u0430\u0431\u043e\u0442\u044b, \u0430 \u043d\u0435 \u0434\u043b\u044f \u0434\u043e\u0441\u0442\u0438\u0436\u0435\u043d\u0438\u0439. \u0422\u043e, \u0447\u0442\u043e \u0432\u044b \u043d\u0430\u0447\u0430\u043b\u0438, \u0443\u0436\u0435 \u0440\u0430\u0441\u0442\u0451\u0442 \u2014 \u0435\u043c\u0443 \u043d\u0443\u0436\u043d\u044b \u043d\u0435 \u0443\u0441\u0438\u043b\u0438\u044f, \u0430 \u0432\u0440\u0435\u043c\u044f \u0438 \u0432\u043d\u0438\u043c\u0430\u043d\u0438\u0435. \u0425\u043e\u0440\u043e\u0448\u043e \u0434\u043b\u044f \u0434\u043e\u043c\u0430, \u0434\u043b\u044f \u0442\u0435\u0445, \u043a\u0442\u043e \u0440\u044f\u0434\u043e\u043c, \u0434\u043b\u044f \u0442\u0435\u043b\u0430: \u043f\u043e\u0435\u0448\u044c\u0442\u0435 \u043d\u043e\u0440\u043c\u0430\u043b\u044c\u043d\u043e, \u0432\u044b\u0441\u043f\u0438\u0442\u0435\u0441\u044c, \u0432\u044b\u0439\u0434\u0438\u0442\u0435 \u043d\u0430 \u0432\u043e\u0437\u0434\u0443\u0445. \u0418\u0437\u043e\u0431\u0438\u043b\u0438\u0435 \u0432 \u044d\u0442\u043e\u0439 \u043a\u0430\u0440\u0442\u0435 \u043d\u0435 \u043f\u0440\u043e \u0434\u0435\u043d\u044c\u0433\u0438, \u0430 \u043f\u0440\u043e \u0442\u043e, \u0447\u0442\u043e \u0445\u0432\u0430\u0442\u0430\u0435\u0442 \u2014 \u0438 \u0441\u0435\u0433\u043e\u0434\u043d\u044f \u0441\u0442\u043e\u0438\u0442 \u0437\u0430\u043c\u0435\u0442\u0438\u0442\u044c, \u0447\u0435\u0433\u043e \u0438\u043c\u0435\u043d\u043d\u043e \u0432\u0430\u043c \u0443\u0436\u0435 \u0445\u0432\u0430\u0442\u0430\u0435\u0442.","\u0417\u0430\u0431\u043e\u0442\u0430, \u043a\u043e\u0442\u043e\u0440\u0430\u044f \u0434\u0443\u0448\u0438\u0442. \u0412\u044b \u0432\u043a\u043b\u0430\u0434\u044b\u0432\u0430\u0435\u0442\u0435\u0441\u044c \u0432 \u0442\u043e, \u0447\u0442\u043e \u0434\u0430\u0432\u043d\u043e \u0432\u044b\u0440\u043e\u0441\u043b\u043e \u0438 \u043f\u0440\u043e\u0441\u0438\u0442, \u0447\u0442\u043e\u0431\u044b \u0435\u0433\u043e \u043e\u0441\u0442\u0430\u0432\u0438\u043b\u0438 \u0432 \u043f\u043e\u043a\u043e\u0435, \u2014 \u0438\u043b\u0438, \u043d\u0430\u043e\u0431\u043e\u0440\u043e\u0442, \u0437\u0430\u0431\u044b\u043b\u0438 \u043f\u043e\u043b\u0438\u0442\u044c \u0441\u043e\u0431\u0441\u0442\u0432\u0435\u043d\u043d\u043e\u0435. \u0421\u043f\u0440\u043e\u0441\u0438\u0442\u0435, \u043e \u043a\u043e\u043c \u0432\u044b \u0441\u0435\u0433\u043e\u0434\u043d\u044f \u043d\u0435 \u043f\u043e\u0437\u0430\u0431\u043e\u0442\u0438\u043b\u0438\u0441\u044c.")
B.Op=new A.cs("04","\u0418\u043c\u043f\u0435\u0440\u0430\u0442\u043e\u0440","\u041f\u043e\u0441\u0442\u0430\u0432\u044c\u0442\u0435 \u0433\u0440\u0430\u043d\u0438\u0446\u0443","\u0421\u0435\u0433\u043e\u0434\u043d\u044f \u0440\u0430\u0431\u043e\u0442\u0430\u0435\u0442 \u043f\u043e\u0440\u044f\u0434\u043e\u043a, \u0430 \u043d\u0435 \u0432\u0434\u043e\u0445\u043d\u043e\u0432\u0435\u043d\u0438\u0435. \u0420\u0435\u0448\u0438\u0442\u0435, \u0447\u0442\u043e \u0432\u044b \u0434\u0435\u043b\u0430\u0435\u0442\u0435 \u0438 \u0447\u0435\u0433\u043e \u043d\u0435 \u0434\u0435\u043b\u0430\u0435\u0442\u0435, \u0438 \u0434\u0435\u0440\u0436\u0438\u0442\u0435\u0441\u044c \u044d\u0442\u043e\u0433\u043e \u0434\u043e \u0432\u0435\u0447\u0435\u0440\u0430. \u0425\u043e\u0440\u043e\u0448\u0438\u0439 \u0434\u0435\u043d\u044c, \u0447\u0442\u043e\u0431\u044b \u0441\u043a\u0430\u0437\u0430\u0442\u044c \xab\u043d\u0435\u0442\xbb \u0442\u043e\u043c\u0443, \u0447\u0442\u043e \u0442\u044f\u043d\u0435\u0442\u0441\u044f \u0431\u0435\u0437 \u043a\u043e\u043d\u0446\u0430, \u0438 \u043d\u0430\u0437\u043d\u0430\u0447\u0438\u0442\u044c \u0441\u0440\u043e\u043a \u0442\u043e\u043c\u0443, \u0447\u0442\u043e \u0442\u044f\u043d\u0435\u0442\u0441\u044f \u0431\u0435\u0437 \u0441\u0440\u043e\u043a\u0430. \u0421\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u0430 \u043d\u0435 \u043e\u0433\u0440\u0430\u043d\u0438\u0447\u0438\u0432\u0430\u0435\u0442 \u2014 \u043e\u043d\u0430 \u043e\u0441\u0432\u043e\u0431\u043e\u0436\u0434\u0430\u0435\u0442 \u043e\u0442 \u043d\u0435\u043e\u0431\u0445\u043e\u0434\u0438\u043c\u043e\u0441\u0442\u0438 \u0440\u0435\u0448\u0430\u0442\u044c \u0437\u0430\u043d\u043e\u0432\u043e \u043a\u0430\u0436\u0434\u044b\u0435 \u043f\u043e\u043b\u0447\u0430\u0441\u0430.","\u041f\u043e\u0440\u044f\u0434\u043e\u043a \u0440\u0430\u0434\u0438 \u043f\u043e\u0440\u044f\u0434\u043a\u0430. \u041f\u0440\u0430\u0432\u0438\u043b\u043e, \u043a\u043e\u0442\u043e\u0440\u043e\u0435 \u0432\u044b \u0434\u0435\u0440\u0436\u0438\u0442\u0435, \u0443\u0436\u0435 \u043d\u0438\u043a\u043e\u0433\u043e \u043d\u0435 \u0437\u0430\u0449\u0438\u0449\u0430\u0435\u0442, \u0432\u043a\u043b\u044e\u0447\u0430\u044f \u0432\u0430\u0441. \u041b\u0438\u0431\u043e \u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u044b \u043d\u0435 \u0445\u0432\u0430\u0442\u0430\u0435\u0442 \u0441\u043e\u0432\u0441\u0435\u043c \u0438 \u0432\u0441\u0451 \u0434\u0435\u0440\u0436\u0438\u0442\u0441\u044f \u043d\u0430 \u0442\u043e\u043c, \u0447\u0442\u043e \u0432\u044b \u043a\u0430\u0436\u0434\u044b\u0439 \u0440\u0430\u0437 \u0432\u0441\u0451 \u043f\u043e\u043c\u043d\u0438\u0442\u0435 \u0441\u0430\u043c\u0438.")
B.Ou=new A.cs("05","\u0418\u0435\u0440\u043e\u0444\u0430\u043d\u0442","\u0421\u043f\u0440\u043e\u0441\u0438\u0442\u0435 \u0443 \u0442\u043e\u0433\u043e, \u043a\u0442\u043e \u043f\u0440\u043e\u0448\u0451\u043b","\u041d\u0435 \u0438\u0437\u043e\u0431\u0440\u0435\u0442\u0430\u0439\u0442\u0435 \u0437\u0430\u043d\u043e\u0432\u043e \u0442\u043e, \u0447\u0442\u043e \u043f\u0440\u0438\u0434\u0443\u043c\u0430\u043d\u043e \u0434\u043e \u0432\u0430\u0441. \u0421\u0435\u0433\u043e\u0434\u043d\u044f \u043a\u043e\u0440\u043e\u0442\u043a\u0438\u0439 \u043f\u0443\u0442\u044c \u043b\u0435\u0436\u0438\u0442 \u0447\u0435\u0440\u0435\u0437 \u0447\u0443\u0436\u043e\u0439 \u043e\u043f\u044b\u0442: \u0441\u043f\u0440\u043e\u0441\u0438\u0442\u0435 \u0443 \u0442\u043e\u0433\u043e, \u043a\u0442\u043e \u0434\u0430\u043b\u044c\u0448\u0435 \u0432 \u044d\u0442\u043e\u043c \u0434\u0435\u043b\u0435, \u043f\u0440\u043e\u0447\u0438\u0442\u0430\u0439\u0442\u0435, \u043a\u0430\u043a \u043f\u0440\u0438\u043d\u044f\u0442\u043e, \u0441\u0434\u0435\u043b\u0430\u0439\u0442\u0435 \u043f\u043e \u043f\u0440\u0430\u0432\u0438\u043b\u0430\u043c. \u0412 \u044d\u0442\u043e\u043c \u043d\u0435\u0442 \u043e\u0442\u043a\u0430\u0437\u0430 \u043e\u0442 \u0441\u0435\u0431\u044f \u2014 \u043f\u0440\u0430\u0432\u0438\u043b\u043e \u0441\u0443\u0449\u0435\u0441\u0442\u0432\u0443\u0435\u0442 \u043f\u043e\u0442\u043e\u043c\u0443, \u0447\u0442\u043e \u043a\u0442\u043e-\u0442\u043e \u0443\u0436\u0435 \u043d\u0430\u0431\u0438\u043b \u0432\u0441\u0435 \u0448\u0438\u0448\u043a\u0438. \u0421\u0432\u043e\u0451 \u043f\u0440\u0438\u0434\u0451\u0442 \u043f\u043e\u0441\u043b\u0435, \u0438 \u0431\u0443\u0434\u0435\u0442 \u043f\u0440\u043e\u0447\u043d\u0435\u0435.","\xab\u0422\u0430\u043a \u043f\u0440\u0438\u043d\u044f\u0442\u043e\xbb \u2014 \u0438 \u043d\u0438\u043a\u0442\u043e \u0443\u0436\u0435 \u043d\u0435 \u043f\u043e\u043c\u043d\u0438\u0442 \u043f\u043e\u0447\u0435\u043c\u0443. \u0421\u0435\u0433\u043e\u0434\u043d\u044f \u0441\u0442\u043e\u0438\u0442 \u0441\u043f\u0440\u043e\u0441\u0438\u0442\u044c, \u0447\u0435\u0439 \u044d\u0442\u043e \u043d\u0430 \u0441\u0430\u043c\u043e\u043c \u0434\u0435\u043b\u0435 \u0433\u043e\u043b\u043e\u0441: \u0432\u0430\u0448, \u0440\u043e\u0434\u0438\u0442\u0435\u043b\u044c\u0441\u043a\u0438\u0439 \u0438\u043b\u0438 \u043f\u0440\u043e\u0441\u0442\u043e \u043f\u0440\u0438\u0432\u044b\u0447\u043a\u0430 \u043c\u0435\u0441\u0442\u0430, \u0433\u0434\u0435 \u0432\u044b \u0440\u0430\u0431\u043e\u0442\u0430\u0435\u0442\u0435.")
B.OE=new A.cs("06","\u0412\u043b\u044e\u0431\u043b\u0451\u043d\u043d\u044b\u0435","\u0412\u044b\u0431\u043e\u0440, \u0430 \u043d\u0435 \u043a\u043e\u043b\u0435\u0431\u0430\u043d\u0438\u0435","\u041f\u0435\u0440\u0435\u0434 \u0432\u0430\u043c\u0438 \u043d\u0435 \xab\u0445\u043e\u0440\u043e\u0448\u0435\u0435 \u0438 \u043f\u043b\u043e\u0445\u043e\u0435\xbb, \u0430 \u0434\u0432\u0430 \u0445\u043e\u0440\u043e\u0448\u0438\u0445, \u0438 \u043f\u043e\u0442\u043e\u043c\u0443 \u0442\u0430\u043a \u0442\u0440\u0443\u0434\u043d\u043e. \u041a\u0430\u0440\u0442\u0430 \u043d\u0435 \u043f\u0440\u043e \u0440\u043e\u043c\u0430\u043d\u0442\u0438\u043a\u0443, \u0430 \u043f\u0440\u043e \u0440\u0435\u0448\u0435\u043d\u0438\u0435, \u043a\u043e\u0442\u043e\u0440\u043e\u0435 \u043e\u043f\u0440\u0435\u0434\u0435\u043b\u044f\u0435\u0442, \u043a\u0435\u043c \u0432\u044b \u0431\u0443\u0434\u0435\u0442\u0435 \u0434\u0430\u043b\u044c\u0448\u0435. \u0421\u0435\u0433\u043e\u0434\u043d\u044f \u0441\u0442\u043e\u0438\u0442 \u0432\u044b\u0431\u0440\u0430\u0442\u044c \u2014 \u043b\u044e\u0431\u043e\u0435 \u0438\u0437 \u0434\u0432\u0443\u0445 \u043b\u0443\u0447\u0448\u0435 \u0442\u0440\u0435\u0442\u044c\u0435\u0433\u043e \u0434\u043d\u044f \u0432 \u043f\u043e\u0434\u0432\u0435\u0448\u0435\u043d\u043d\u043e\u043c \u0441\u043e\u0441\u0442\u043e\u044f\u043d\u0438\u0438. \u0421\u043f\u0440\u043e\u0441\u0438\u0442\u0435 \u0441\u0435\u0431\u044f \u043d\u0435 \xab\u0447\u0442\u043e \u0432\u044b\u0433\u043e\u0434\u043d\u0435\u0435\xbb, \u0430 \xab\u0441 \u0447\u0435\u043c \u044f \u0441\u043c\u043e\u0433\u0443 \u0436\u0438\u0442\u044c\xbb. \u0418 \u043d\u0435 \u0441\u043f\u0440\u0430\u0448\u0438\u0432\u0430\u0439\u0442\u0435 \u0441\u043e\u0432\u0435\u0442\u0430 \u0443 \u0441\u043b\u0438\u0448\u043a\u043e\u043c \u043c\u043d\u043e\u0433\u0438\u0445: \u044d\u0442\u043e\u0442 \u0432\u044b\u0431\u043e\u0440 \u043d\u0435\u043b\u044c\u0437\u044f \u0434\u0435\u043b\u0435\u0433\u0438\u0440\u043e\u0432\u0430\u0442\u044c, \u0430 \u0447\u0443\u0436\u0438\u0435 \u043c\u043d\u0435\u043d\u0438\u044f \u0442\u043e\u043b\u044c\u043a\u043e \u043e\u0442\u0442\u044f\u043d\u0443\u0442 \u0435\u0433\u043e \u0435\u0449\u0451 \u043d\u0430 \u043d\u0435\u0434\u0435\u043b\u044e.","\u0412\u044b\u0431\u043e\u0440, \u043a\u043e\u0442\u043e\u0440\u044b\u0439 \u0432\u044b \u0434\u0435\u043b\u0430\u0435\u0442\u0435, \u043d\u0435 \u0432\u044b\u0431\u0438\u0440\u0430\u044f, \u2014 \u043d\u0430\u0434\u0435\u044f\u0441\u044c, \u0447\u0442\u043e \u0440\u0435\u0448\u0438\u0442\u0441\u044f \u0441\u0430\u043c\u043e. \u041e\u043d\u043e \u0440\u0435\u0448\u0438\u0442\u0441\u044f, \u043d\u043e \u043d\u0435 \u0432 \u0432\u0430\u0448\u0443 \u043f\u043e\u043b\u044c\u0437\u0443. \u0417\u0434\u0435\u0441\u044c \u0432\u0430\u0436\u043d\u0430 \u043d\u0435 \u043b\u044e\u0431\u043e\u0432\u044c, \u0430 \u0447\u0435\u0441\u0442\u043d\u043e\u0441\u0442\u044c \u043e \u0442\u043e\u043c, \u0447\u0435\u0433\u043e \u0432\u044b \u0445\u043e\u0442\u0438\u0442\u0435 \u043d\u0430 \u0441\u0430\u043c\u043e\u043c \u0434\u0435\u043b\u0435.")
B.OA=new A.cs("07","\u041a\u043e\u043b\u0435\u0441\u043d\u0438\u0446\u0430","\u0414\u0435\u0440\u0436\u0438\u0442\u0435 \u043d\u0430\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u0435","\u0421\u0438\u043b \u0445\u0432\u0430\u0442\u0430\u0435\u0442, \u0438 \u044d\u0442\u043e \u043d\u0435 \u0433\u043b\u0430\u0432\u043d\u0430\u044f \u043f\u0440\u043e\u0431\u043b\u0435\u043c\u0430. \u0413\u043b\u0430\u0432\u043d\u0430\u044f \u2014 \u0447\u0442\u043e \u0434\u0432\u0430 \u043a\u043e\u043d\u044f \u0442\u044f\u043d\u0443\u0442 \u0432 \u0440\u0430\u0437\u043d\u044b\u0435 \u0441\u0442\u043e\u0440\u043e\u043d\u044b: \u0434\u0432\u0430 \u0434\u0435\u043b\u0430, \u0434\u0432\u0435 \u043e\u0431\u044f\u0437\u0430\u043d\u043d\u043e\u0441\u0442\u0438, \u0434\u0432\u0430 \u0436\u0435\u043b\u0430\u043d\u0438\u044f. \u0421\u0435\u0433\u043e\u0434\u043d\u044f \u0432\u044b\u0438\u0433\u0440\u044b\u0432\u0430\u0435\u0442 \u043d\u0435 \u0442\u043e\u0442, \u043a\u0442\u043e \u0431\u044b\u0441\u0442\u0440\u0435\u0435, \u0430 \u0442\u043e\u0442, \u043a\u0442\u043e \u043d\u0435 \u0441\u0432\u043e\u0440\u0430\u0447\u0438\u0432\u0430\u0435\u0442. \u0412\u044b\u0431\u0435\u0440\u0438\u0442\u0435 \u043e\u0434\u043d\u043e \u043d\u0430\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u0435 \u043d\u0430 \u0434\u0435\u043d\u044c \u0438 \u0434\u043e\u0432\u0435\u0434\u0438\u0442\u0435 \u0434\u043e \u0432\u0435\u0447\u0435\u0440\u0430, \u0434\u0430\u0436\u0435 \u0435\u0441\u043b\u0438 \u0432\u0442\u043e\u0440\u043e\u0435 \u0432\u044b\u0433\u043b\u044f\u0434\u0438\u0442 \u0441\u0440\u043e\u0447\u043d\u0435\u0435. \u0412\u0442\u043e\u0440\u043e\u0435 \u043d\u0438\u043a\u0443\u0434\u0430 \u043d\u0435 \u0434\u0435\u043d\u0435\u0442\u0441\u044f. \u041e\u043d\u043e \u0431\u0443\u0434\u0435\u0442 \u0436\u0434\u0430\u0442\u044c \u0432\u0430\u0441 \u0437\u0430\u0432\u0442\u0440\u0430 \u0440\u043e\u0432\u043d\u043e \u0442\u0430\u043c \u0436\u0435, \u0433\u0434\u0435 \u0441\u0442\u043e\u0438\u0442 \u0441\u0435\u0439\u0447\u0430\u0441.","\u041c\u043d\u043e\u0433\u043e \u0434\u0432\u0438\u0436\u0435\u043d\u0438\u044f \u0438 \u043c\u0430\u043b\u043e \u043d\u0430\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u044f. \u041a\u043e\u043d\u0438 \u0442\u044f\u043d\u0443\u0442 \u0432 \u0440\u0430\u0437\u043d\u044b\u0435 \u0441\u0442\u043e\u0440\u043e\u043d\u044b, \u0430 \u0432\u044b \u043d\u0430\u0437\u044b\u0432\u0430\u0435\u0442\u0435 \u044d\u0442\u043e \u0437\u0430\u043d\u044f\u0442\u043e\u0441\u0442\u044c\u044e. \u041e\u0441\u0442\u0430\u043d\u043e\u0432\u0438\u0442\u044c\u0441\u044f \u0441\u0435\u0433\u043e\u0434\u043d\u044f \u0431\u044b\u0441\u0442\u0440\u0435\u0435, \u0447\u0435\u043c \u0435\u0445\u0430\u0442\u044c.")
B.Or=new A.cs("08","\u0421\u0438\u043b\u0430","\u041c\u044f\u0433\u043a\u043e, \u043d\u043e \u043d\u0435 \u043e\u0442\u0441\u0442\u0443\u043f\u0430\u044f","\u0416\u0435\u043d\u0449\u0438\u043d\u0430 \u043d\u0430 \u043a\u0430\u0440\u0442\u0435 \u0437\u0430\u043a\u0440\u044b\u0432\u0430\u0435\u0442 \u043b\u044c\u0432\u0443 \u043f\u0430\u0441\u0442\u044c \u0431\u0435\u0437 \u0443\u0441\u0438\u043b\u0438\u044f \u2014 \u043d\u0435 \u0441\u0438\u043b\u043e\u0439, \u0430 \u0441\u043f\u043e\u043a\u043e\u0439\u0441\u0442\u0432\u0438\u0435\u043c. \u0421\u0435\u0433\u043e\u0434\u043d\u044f\u0448\u043d\u0435\u0435 \u0441\u043e\u043f\u0440\u043e\u0442\u0438\u0432\u043b\u0435\u043d\u0438\u0435, \u0447\u0443\u0436\u043e\u0435 \u0438\u043b\u0438 \u0441\u0432\u043e\u0451, \u043d\u0435 \u043b\u043e\u043c\u0430\u0435\u0442\u0441\u044f \u043d\u0430\u0436\u0438\u043c\u043e\u043c. \u0422\u0435\u0440\u043f\u0435\u043d\u0438\u0435 \u0441\u0440\u0430\u0431\u043e\u0442\u0430\u0435\u0442 \u0442\u0430\u043c, \u0433\u0434\u0435 \u043d\u0430\u043f\u043e\u0440 \u0442\u043e\u043b\u044c\u043a\u043e \u0437\u0430\u0432\u0435\u0434\u0451\u0442. \u042d\u0442\u043e \u043e\u0442\u043d\u043e\u0441\u0438\u0442\u0441\u044f \u0438 \u043a \u0440\u0430\u0437\u0433\u043e\u0432\u043e\u0440\u0443, \u043a\u043e\u0442\u043e\u0440\u044b\u0439 \u0432\u044b \u043f\u0440\u0435\u0434\u0432\u0438\u0434\u0438\u0442\u0435, \u0438 \u043a \u043f\u0440\u0438\u0432\u044b\u0447\u043a\u0435, \u043a\u043e\u0442\u043e\u0440\u0443\u044e \u043f\u044b\u0442\u0430\u0435\u0442\u0435\u0441\u044c \u043f\u0435\u0440\u0435\u043b\u043e\u043c\u0438\u0442\u044c. \u0418 \u043a \u0441\u0435\u0431\u0435 \u0442\u043e\u0436\u0435: \u0435\u0441\u043b\u0438 \u0441\u0435\u0433\u043e\u0434\u043d\u044f \u043d\u0435 \u0432\u044b\u0448\u043b\u043e, \u044d\u0442\u043e \u043d\u0435 \u043f\u043e\u0432\u043e\u0434 \u0434\u0430\u0432\u0438\u0442\u044c. \u0417\u0430\u0432\u0442\u0440\u0430 \u043b\u0435\u0432 \u0431\u0443\u0434\u0435\u0442 \u0441\u043f\u043e\u043a\u043e\u0439\u043d\u0435\u0435.","\u0421\u0438\u043b\u0443 \u043f\u0443\u0442\u0430\u044e\u0442 \u0441 \u043d\u0430\u043f\u0440\u044f\u0436\u0435\u043d\u0438\u0435\u043c. \u0412\u044b \u0434\u0430\u0432\u0438\u0442\u0435 \u0442\u0430\u043c, \u0433\u0434\u0435 \u043d\u0443\u0436\u043d\u043e \u0431\u044b\u043b\u043e \u043e\u0442\u043f\u0443\u0441\u0442\u0438\u0442\u044c, \u0438 \u0443\u0441\u0442\u0430\u0451\u0442\u0435 \u043e\u0442 \u0441\u043e\u0431\u0441\u0442\u0432\u0435\u043d\u043d\u043e\u0439 \u0445\u0432\u0430\u0442\u043a\u0438. \u041c\u044f\u0433\u043a\u043e\u0441\u0442\u044c \u0437\u0434\u0435\u0441\u044c \u2014 \u043d\u0435 \u0441\u043b\u0430\u0431\u043e\u0441\u0442\u044c, \u0430 \u0435\u0434\u0438\u043d\u0441\u0442\u0432\u0435\u043d\u043d\u043e\u0435, \u0447\u0442\u043e \u0441\u0440\u0430\u0431\u043e\u0442\u0430\u0435\u0442.")
B.Ot=new A.cs("09","\u041e\u0442\u0448\u0435\u043b\u044c\u043d\u0438\u043a","\u041e\u0442\u043e\u0439\u0434\u0438\u0442\u0435 \u0438 \u043f\u043e\u0441\u043c\u043e\u0442\u0440\u0438\u0442\u0435","\u0414\u0435\u043d\u044c \u0434\u043b\u044f \u0442\u0438\u0448\u0438\u043d\u044b \u0438 \u043e\u0434\u043d\u043e\u0433\u043e \u0447\u0435\u0441\u0442\u043d\u043e\u0433\u043e \u0432\u043e\u043f\u0440\u043e\u0441\u0430 \u043a \u0441\u0435\u0431\u0435. \u041e\u0442\u0448\u0435\u043b\u044c\u043d\u0438\u043a \u0441\u0432\u0435\u0442\u0438\u0442 \u0444\u043e\u043d\u0430\u0440\u0451\u043c \u0441\u0435\u0431\u0435 \u043f\u043e\u0434 \u043d\u043e\u0433\u0438, \u0430 \u043d\u0435 \u0434\u0440\u0443\u0433\u0438\u043c \u0432 \u043b\u0438\u0446\u043e. \u041d\u0435 \u0438\u0449\u0438\u0442\u0435 \u0441\u0435\u0433\u043e\u0434\u043d\u044f \u0441\u043e\u0432\u0435\u0442\u0430 \u0441\u043d\u0430\u0440\u0443\u0436\u0438 \u2014 \u0432\u044b \u0443\u0436\u0435 \u0437\u043d\u0430\u0435\u0442\u0435 \u043e\u0442\u0432\u0435\u0442, \u043f\u0440\u043e\u0441\u0442\u043e \u043d\u0435 \u0434\u0430\u0432\u0430\u043b\u0438 \u0441\u0435\u0431\u0435 \u0432\u0440\u0435\u043c\u0435\u043d\u0438 \u0435\u0433\u043e \u0443\u0441\u043b\u044b\u0448\u0430\u0442\u044c. \u0427\u0430\u0441 \u0431\u0435\u0437 \u0442\u0435\u043b\u0435\u0444\u043e\u043d\u0430 \u0441\u0434\u0435\u043b\u0430\u0435\u0442 \u0431\u043e\u043b\u044c\u0448\u0435, \u0447\u0435\u043c \u0442\u0440\u0438 \u0440\u0430\u0437\u0433\u043e\u0432\u043e\u0440\u0430. \u0418 \u043d\u0435 \u043f\u0443\u0442\u0430\u0439\u0442\u0435 \u043e\u0434\u0438\u043d\u043e\u0447\u0435\u0441\u0442\u0432\u043e \u0441 \u0443\u0445\u043e\u0434\u043e\u043c: \u041e\u0442\u0448\u0435\u043b\u044c\u043d\u0438\u043a \u0432\u0435\u0440\u043d\u0451\u0442\u0441\u044f, \u043e\u043d \u043f\u0440\u043e\u0441\u0442\u043e \u043e\u0442\u043e\u0448\u0451\u043b \u043d\u0430\u0441\u0442\u043e\u043b\u044c\u043a\u043e, \u0447\u0442\u043e\u0431\u044b \u0441\u0442\u0430\u043b\u043e \u0432\u0438\u0434\u043d\u043e \u0446\u0435\u043b\u0438\u043a\u043e\u043c.","\u0423\u0435\u0434\u0438\u043d\u0435\u043d\u0438\u0435 \u0441\u0442\u0430\u043b\u043e \u0443\u0431\u0435\u0436\u0438\u0449\u0435\u043c. \u041e\u0434\u043d\u043e\u043c\u0443 \u0431\u044b\u043b\u043e \u043f\u043e\u043b\u0435\u0437\u043d\u043e \u043d\u0435\u0434\u0435\u043b\u044e \u043d\u0430\u0437\u0430\u0434; \u0441\u0435\u0433\u043e\u0434\u043d\u044f \u044d\u0442\u043e \u0441\u043f\u043e\u0441\u043e\u0431 \u043d\u0435 \u043f\u043e\u043a\u0430\u0437\u044b\u0432\u0430\u0442\u044c\u0441\u044f. \u041e\u0434\u0438\u043d \u0440\u0430\u0437\u0433\u043e\u0432\u043e\u0440 \u0432\u0435\u0440\u043d\u0451\u0442 \u0431\u043e\u043b\u044c\u0448\u0435, \u0447\u0435\u043c \u0435\u0449\u0451 \u0434\u0435\u043d\u044c \u0440\u0430\u0437\u043c\u044b\u0448\u043b\u0435\u043d\u0438\u0439.")
B.OH=new A.cs("10","\u041a\u043e\u043b\u0435\u0441\u043e","\u041f\u043e\u043b\u043e\u0441\u0430 \u043f\u043e\u0432\u043e\u0440\u0430\u0447\u0438\u0432\u0430\u0435\u0442","\u0422\u043e, \u0447\u0442\u043e \u0442\u044f\u043d\u0443\u043b\u043e\u0441\u044c, \u0441\u0434\u0432\u0438\u043d\u0435\u0442\u0441\u044f \u0441\u0430\u043c\u043e \u2014 \u043d\u0435 \u0432\u0430\u0448\u0438\u043c\u0438 \u0443\u0441\u0438\u043b\u0438\u044f\u043c\u0438, \u0430 \u043f\u043e\u0442\u043e\u043c\u0443 \u0447\u0442\u043e \u043f\u0440\u0438\u0448\u0451\u043b \u0441\u0440\u043e\u043a. \u042d\u0442\u043e \u0440\u0430\u0431\u043e\u0442\u0430\u0435\u0442 \u0432 \u043e\u0431\u0435 \u0441\u0442\u043e\u0440\u043e\u043d\u044b, \u043f\u043e\u044d\u0442\u043e\u043c\u0443 \u0441\u0435\u0433\u043e\u0434\u043d\u044f \u043d\u0435 \u0432\u0440\u0435\u043c\u044f \u0434\u043b\u044f \u0441\u0442\u0430\u0432\u043e\u043a \u0438 \u0440\u0435\u0437\u043a\u0438\u0445 \u0440\u0435\u0448\u0435\u043d\u0438\u0439. \u041f\u0440\u0438\u043c\u0438\u0442\u0435 \u0442\u043e, \u0447\u0442\u043e \u043f\u0440\u043e\u0438\u0441\u0445\u043e\u0434\u0438\u0442, \u0438 \u043d\u0435 \u043f\u0440\u0438\u043f\u0438\u0441\u044b\u0432\u0430\u0439\u0442\u0435 \u0441\u0435\u0431\u0435 \u043d\u0438 \u0443\u0434\u0430\u0447\u0443, \u043d\u0438 \u043d\u0435\u0443\u0434\u0430\u0447\u0443: \u043a\u043e\u043b\u0435\u0441\u043e \u043a\u0440\u0443\u0442\u0438\u0442\u0441\u044f \u0438 \u0431\u0435\u0437 \u043d\u0430\u0441. \u041b\u0443\u0447\u0448\u0435\u0435, \u0447\u0442\u043e \u043c\u043e\u0436\u043d\u043e \u0441\u0434\u0435\u043b\u0430\u0442\u044c \u0432 \u0442\u0430\u043a\u043e\u0439 \u0434\u0435\u043d\u044c, \u2014 \u043f\u043e\u0434\u0433\u043e\u0442\u043e\u0432\u0438\u0442\u044c\u0441\u044f \u043a \u0442\u043e\u043c\u0443, \u0447\u0442\u043e \u0443\u0436\u0435 \u0432\u0438\u0434\u043d\u043e \u043d\u0430 \u043f\u043e\u0434\u0445\u043e\u0434\u0435, \u0438 \u043d\u0435 \u0442\u0440\u0430\u0442\u0438\u0442\u044c \u0441\u0438\u043b\u044b \u043d\u0430 \u043f\u043e\u043f\u044b\u0442\u043a\u0438 \u043e\u0441\u0442\u0430\u043d\u043e\u0432\u0438\u0442\u044c \u0434\u0432\u0438\u0436\u0435\u043d\u0438\u0435. \u041a\u043e\u043b\u0435\u0441\u043e \u0432\u0441\u0451 \u0440\u0430\u0432\u043d\u043e \u043f\u0440\u043e\u0432\u0435\u0440\u043d\u0451\u0442\u0441\u044f.","\u0412\u044b \u0436\u0434\u0451\u0442\u0435, \u0447\u0442\u043e \u043f\u043e\u0432\u0435\u0440\u043d\u0451\u0442\u0441\u044f \u0441\u0430\u043c\u043e. \u0418\u043d\u043e\u0433\u0434\u0430 \u043f\u0440\u0430\u0432\u0434\u0430 \u043f\u043e\u0432\u043e\u0440\u0430\u0447\u0438\u0432\u0430\u0435\u0442\u0441\u044f \u2014 \u043d\u043e \u0441\u0435\u0433\u043e\u0434\u043d\u044f \u043a\u043e\u043b\u0435\u0441\u043e \u0441\u0442\u043e\u0438\u0442 \u0442\u0430\u043c, \u0433\u0434\u0435 \u0432\u044b \u0435\u0433\u043e \u043f\u0440\u0438\u0434\u0435\u0440\u0436\u0438\u0432\u0430\u0435\u0442\u0435. \u0427\u0442\u043e \u0432\u044b \u043d\u0430\u0437\u044b\u0432\u0430\u0435\u0442\u0435 \u043d\u0435\u0432\u0435\u0437\u0435\u043d\u0438\u0435\u043c, \u0445\u043e\u0442\u044f \u044d\u0442\u043e \u0440\u0435\u0448\u0435\u043d\u0438\u0435?")
B.Os=new A.cs("11","\u0421\u043f\u0440\u0430\u0432\u0435\u0434\u043b\u0438\u0432\u043e\u0441\u0442\u044c","\u041f\u043e \u0441\u0447\u0451\u0442\u0443, \u0430 \u043d\u0435 \u043f\u043e \u0447\u0443\u0432\u0441\u0442\u0432\u0443","\u0421\u0435\u0433\u043e\u0434\u043d\u044f \u0432\u0441\u0451 \u0432\u043e\u0437\u0432\u0440\u0430\u0449\u0430\u0435\u0442\u0441\u044f \u0440\u043e\u0432\u043d\u043e \u0432 \u0442\u043e\u043c \u0440\u0430\u0437\u043c\u0435\u0440\u0435, \u0432 \u043a\u0430\u043a\u043e\u043c \u0431\u044b\u043b\u043e \u043e\u0442\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u043e. \u0425\u043e\u0440\u043e\u0448\u0438\u0439 \u0434\u0435\u043d\u044c, \u0447\u0442\u043e\u0431\u044b \u0437\u0430\u043a\u0440\u044b\u0442\u044c \u0434\u043e\u043b\u0433, \u0432\u0435\u0440\u043d\u0443\u0442\u044c \u0447\u0443\u0436\u043e\u0435, \u0441\u043a\u0430\u0437\u0430\u0442\u044c \u043f\u0440\u0430\u0432\u0434\u0443 \u0442\u0430\u043c, \u0433\u0434\u0435 \u0432\u044b \u0435\u0451 \u0441\u043c\u044f\u0433\u0447\u0430\u043b\u0438. \u0418 \u043f\u043b\u043e\u0445\u043e\u0439, \u0447\u0442\u043e\u0431\u044b \u043b\u043e\u0432\u0447\u0438\u0442\u044c: \u043c\u0435\u043b\u043a\u0430\u044f \u043d\u0435\u0447\u0435\u0441\u0442\u043d\u043e\u0441\u0442\u044c \u0441\u0435\u0433\u043e\u0434\u043d\u044f \u043e\u0431\u043e\u0439\u0434\u0451\u0442\u0441\u044f \u0434\u043e\u0440\u043e\u0436\u0435 \u043e\u0431\u044b\u0447\u043d\u043e\u0433\u043e. \u0412\u0437\u0432\u0435\u0441\u044c\u0442\u0435 \u0447\u0435\u0441\u0442\u043d\u043e \u2014 \u0432 \u0442\u043e\u043c \u0447\u0438\u0441\u043b\u0435 \u0441\u0435\u0431\u044f. \u0418 \u043d\u0435 \u0436\u0434\u0438\u0442\u0435, \u0447\u0442\u043e \u043a\u0442\u043e-\u0442\u043e \u0440\u0430\u0441\u0441\u0443\u0434\u0438\u0442 \u0437\u0430 \u0432\u0430\u0441: \u043c\u0435\u0447 \u0443 \u0421\u043f\u0440\u0430\u0432\u0435\u0434\u043b\u0438\u0432\u043e\u0441\u0442\u0438 \u0432 \u043f\u0440\u0430\u0432\u043e\u0439 \u0440\u0443\u043a\u0435, \u0430 \u0432\u0435\u0441\u044b \u0432 \u043b\u0435\u0432\u043e\u0439 \u2014 \u043e\u043d\u0430 \u0440\u0435\u0448\u0430\u0435\u0442 \u0438 \u0438\u0441\u043f\u043e\u043b\u043d\u044f\u0435\u0442 \u0441\u0430\u043c\u0430.","\u0412\u0435\u0441\u044b, \u043d\u0430 \u043a\u043e\u0442\u043e\u0440\u044b\u0445 \u0432\u0437\u0432\u0435\u0448\u0438\u0432\u0430\u044e\u0442 \u0442\u043e\u043b\u044c\u043a\u043e \u0447\u0443\u0436\u043e\u0435. \u0421\u0442\u0440\u043e\u0433\u043e\u0441\u0442\u044c \u043a \u0434\u0440\u0443\u0433\u0438\u043c \u0438 \u0441\u043a\u0438\u0434\u043a\u0430 \u0441\u0435\u0431\u0435 \u2014 \u0438\u043b\u0438 \u0440\u043e\u0432\u043d\u043e \u043d\u0430\u043e\u0431\u043e\u0440\u043e\u0442, \u0438 \u0432\u044b \u0441\u0443\u0434\u0438\u0442\u0435 \u0441\u0435\u0431\u044f \u043f\u043e \u043c\u0435\u0440\u043a\u0435, \u043a\u043e\u0442\u043e\u0440\u0443\u044e \u043d\u0438\u043a\u043e\u043c\u0443 \u0431\u043e\u043b\u044c\u0448\u0435 \u043d\u0435 \u043f\u0440\u0435\u0434\u044a\u044f\u0432\u0438\u043b\u0438 \u0431\u044b.")
B.Oy=new A.cs("12","\u041f\u043e\u0432\u0435\u0448\u0435\u043d\u043d\u044b\u0439","\u041f\u0430\u0443\u0437\u0430 \u2014 \u0442\u043e\u0436\u0435 \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0435","\u0414\u0435\u043b\u043e \u0441\u0442\u043e\u0438\u0442, \u0438 \u043f\u043e\u0434\u0442\u043e\u043b\u043a\u043d\u0443\u0442\u044c \u0435\u0433\u043e \u043d\u0435\u043b\u044c\u0437\u044f. \u0415\u0434\u0438\u043d\u0441\u0442\u0432\u0435\u043d\u043d\u043e\u0435, \u0447\u0442\u043e \u0434\u043e\u0441\u0442\u0443\u043f\u043d\u043e, \u2014 \u043f\u043e\u0441\u043c\u043e\u0442\u0440\u0435\u0442\u044c \u043d\u0430 \u043d\u0435\u0433\u043e \u0438\u043d\u0430\u0447\u0435. \u041f\u043e\u0432\u0435\u0448\u0435\u043d\u043d\u044b\u0439 \u0432\u0438\u0441\u0438\u0442 \u0432\u043d\u0438\u0437 \u0433\u043e\u043b\u043e\u0432\u043e\u0439 \u0434\u043e\u0431\u0440\u043e\u0432\u043e\u043b\u044c\u043d\u043e: \u043e\u043d \u043d\u0435 \u043d\u0430\u043a\u0430\u0437\u0430\u043d, \u043e\u043d \u0441\u043c\u0435\u043d\u0438\u043b \u0442\u043e\u0447\u043a\u0443 \u0437\u0440\u0435\u043d\u0438\u044f. \u0421\u0435\u0433\u043e\u0434\u043d\u044f \u043d\u0435 \u0442\u0440\u0430\u0442\u044c\u0442\u0435 \u0441\u0438\u043b\u044b \u043d\u0430 \u0442\u043e, \u0447\u0442\u043e\u0431\u044b \u0441\u0434\u0432\u0438\u043d\u0443\u0442\u044c \u043d\u0435\u043f\u043e\u0434\u0432\u0438\u0436\u043d\u043e\u0435; \u043f\u043e\u0442\u0440\u0430\u0442\u044c\u0442\u0435 \u0438\u0445 \u043d\u0430 \u0442\u043e, \u0447\u0442\u043e\u0431\u044b \u043f\u043e\u043d\u044f\u0442\u044c, \u043f\u043e\u0447\u0435\u043c\u0443 \u043e\u043d\u043e \u043d\u0435\u043f\u043e\u0434\u0432\u0438\u0436\u043d\u043e. \u0427\u0430\u0441\u0442\u043e \u043e\u043a\u0430\u0437\u044b\u0432\u0430\u0435\u0442\u0441\u044f, \u0447\u0442\u043e \u0441\u0442\u043e\u0438\u0442 \u043d\u0435 \u0434\u0435\u043b\u043e, \u0430 \u0432\u044b \u2014 \u0434\u0435\u0440\u0436\u0438\u0442\u0435\u0441\u044c \u0437\u0430 \u0432\u0435\u0440\u0441\u0438\u044e, \u0432 \u043a\u043e\u0442\u043e\u0440\u043e\u0439 \u043e\u043d\u043e \u0434\u043e\u043b\u0436\u043d\u043e \u0431\u044b\u043b\u043e \u043f\u043e\u0439\u0442\u0438 \u0438\u043d\u0430\u0447\u0435.","\u041f\u0430\u0443\u0437\u0430, \u043a\u043e\u0442\u043e\u0440\u0430\u044f \u043f\u0435\u0440\u0435\u0441\u0442\u0430\u043b\u0430 \u0431\u044b\u0442\u044c \u043f\u0430\u0443\u0437\u043e\u0439. \u0412\u044b \u0432\u0438\u0441\u0438\u0442\u0435 \u0432\u043d\u0438\u0437 \u0433\u043e\u043b\u043e\u0432\u043e\u0439 \u0443\u0436\u0435 \u0442\u0430\u043a \u0434\u043e\u043b\u0433\u043e, \u0447\u0442\u043e \u043f\u0435\u0440\u0435\u0432\u0451\u0440\u043d\u0443\u0442\u044b\u0439 \u043c\u0438\u0440 \u043a\u0430\u0436\u0435\u0442\u0441\u044f \u043d\u043e\u0440\u043c\u0430\u043b\u044c\u043d\u044b\u043c. \u0416\u0435\u0440\u0442\u0432\u0430 \u0431\u0435\u0437 \u0441\u043c\u044b\u0441\u043b\u0430 \u2014 \u043f\u0440\u043e\u0441\u0442\u043e \u043f\u043e\u0442\u0435\u0440\u044f; \u043f\u0440\u043e\u0432\u0435\u0440\u044c\u0442\u0435, \u0440\u0430\u0434\u0438 \u0447\u0435\u0433\u043e \u0432\u044b \u0436\u0434\u0451\u0442\u0435.")
B.Ox=new A.cs("13","\u0421\u043c\u0435\u0440\u0442\u044c","\u0417\u0430\u043a\u043e\u043d\u0447\u0438\u0442\u0435, \u0447\u0442\u043e\u0431\u044b \u043d\u0430\u0447\u0430\u0442\u044c","\u041a\u0430\u0440\u0442\u0430 \u043d\u0435 \u043f\u0440\u043e \u0431\u0435\u0434\u0443. \u041e\u043d\u0430 \u043f\u0440\u043e \u0442\u043e, \u0447\u0442\u043e \u0447\u0442\u043e-\u0442\u043e \u0443\u0436\u0435 \u0437\u0430\u043a\u043e\u043d\u0447\u0438\u043b\u043e\u0441\u044c, \u0430 \u0432\u044b \u0432\u0441\u0451 \u0435\u0449\u0451 \u044d\u0442\u043e \u043f\u043e\u0434\u0434\u0435\u0440\u0436\u0438\u0432\u0430\u0435\u0442\u0435 \u2014 \u0440\u0430\u0431\u043e\u0442\u0443, \u043f\u0440\u0438\u0432\u044b\u0447\u043a\u0443, \u0440\u0430\u0437\u0433\u043e\u0432\u043e\u0440, \u043a\u043e\u0442\u043e\u0440\u044b\u0439 \u0434\u0430\u0432\u043d\u043e \u0438\u0441\u0447\u0435\u0440\u043f\u0430\u043d. \u0421\u0435\u0433\u043e\u0434\u043d\u044f \u0441\u0442\u043e\u0438\u0442 \u043f\u0440\u0438\u0437\u043d\u0430\u0442\u044c \u043a\u043e\u043d\u0435\u0446 \u0432\u0441\u043b\u0443\u0445. \u041c\u0435\u0441\u0442\u043e \u043e\u0441\u0432\u043e\u0431\u043e\u0434\u0438\u0442\u0441\u044f, \u0438 \u0434\u043e\u0432\u043e\u043b\u044c\u043d\u043e \u0431\u044b\u0441\u0442\u0440\u043e \u043e\u043a\u0430\u0436\u0435\u0442\u0441\u044f, \u0447\u0442\u043e \u043e\u0441\u0432\u043e\u0431\u043e\u0434\u0438\u043b\u043e\u0441\u044c \u0434\u043b\u044f \u0447\u0435\u0433\u043e-\u0442\u043e. \u041d\u0435 \u0442\u043e\u0440\u043e\u043f\u0438\u0442\u0435\u0441\u044c \u0437\u0430\u043f\u043e\u043b\u043d\u044f\u0442\u044c \u043e\u0441\u0432\u043e\u0431\u043e\u0434\u0438\u0432\u0448\u0435\u0435\u0441\u044f \u043f\u0435\u0440\u0432\u044b\u043c, \u0447\u0442\u043e \u043f\u043e\u0434\u0432\u0435\u0440\u043d\u0451\u0442\u0441\u044f. \u041f\u0443\u0441\u0442\u043e\u0435 \u043c\u0435\u0441\u0442\u043e \u2014 \u044d\u0442\u043e \u043d\u0435 \u043f\u0440\u043e\u0431\u043b\u0435\u043c\u0430, \u043a\u043e\u0442\u043e\u0440\u0443\u044e \u043d\u0430\u0434\u043e \u0441\u0440\u043e\u0447\u043d\u043e \u0440\u0435\u0448\u0438\u0442\u044c; \u044d\u0442\u043e \u0438 \u0435\u0441\u0442\u044c \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442 \u0441\u0435\u0433\u043e\u0434\u043d\u044f\u0448\u043d\u0435\u0433\u043e \u0434\u043d\u044f.","\u0412\u044b \u0434\u0435\u0440\u0436\u0438\u0442\u0435 \u0442\u043e, \u0447\u0442\u043e \u0443\u0436\u0435 \u0437\u0430\u043a\u043e\u043d\u0447\u0438\u043b\u043e\u0441\u044c. \u041d\u0435 \u0438\u0437 \u043b\u044e\u0431\u0432\u0438, \u0430 \u043f\u043e\u0442\u043e\u043c\u0443, \u0447\u0442\u043e \u043f\u0440\u0438\u0437\u043d\u0430\u0442\u044c \u043a\u043e\u043d\u0435\u0446 \u2014 \u0437\u043d\u0430\u0447\u0438\u0442 \u043d\u0430\u0447\u0430\u0442\u044c \u0447\u0442\u043e-\u0442\u043e \u043d\u043e\u0432\u043e\u0435, \u0430 \u043d\u0430 \u044d\u0442\u043e \u043d\u0435\u0442 \u0441\u0438\u043b. \u041e\u0442\u043f\u0443\u0449\u0435\u043d\u043d\u043e\u0435 \u043e\u0441\u0432\u043e\u0431\u043e\u0436\u0434\u0430\u0435\u0442 \u0431\u043e\u043b\u044c\u0448\u0435, \u0447\u0435\u043c \u0443\u0434\u0435\u0440\u0436\u0430\u043d\u043d\u043e\u0435.")
B.Oo=new A.cs("14","\u0423\u043c\u0435\u0440\u0435\u043d\u043d\u043e\u0441\u0442\u044c","\u0421\u043c\u0435\u0448\u0430\u0439\u0442\u0435, \u043d\u0435 \u0432\u044b\u0431\u0438\u0440\u0430\u044f","\u0422\u0430\u043c, \u0433\u0434\u0435 \u043a\u0430\u0436\u0435\u0442\u0441\u044f, \u0447\u0442\u043e \u043d\u0430\u0434\u043e \u0432\u044b\u0431\u0440\u0430\u0442\u044c \u043e\u0434\u043d\u043e \u0438\u0437 \u0434\u0432\u0443\u0445, \u0441\u0435\u0433\u043e\u0434\u043d\u044f \u0440\u0430\u0431\u043e\u0442\u0430\u0435\u0442 \u0442\u0440\u0435\u0442\u044c\u0435: \u0441\u043e\u0435\u0434\u0438\u043d\u0438\u0442\u044c. \u041d\u0435\u043c\u043d\u043e\u0433\u043e \u043e\u0434\u043d\u043e\u0433\u043e, \u043d\u0435\u043c\u043d\u043e\u0433\u043e \u0434\u0440\u0443\u0433\u043e\u0433\u043e, \u0438 \u0442\u0435\u0440\u043f\u0435\u043d\u0438\u0435, \u043f\u043e\u043a\u0430 \u0441\u043c\u0435\u0448\u0438\u0432\u0430\u0435\u0442\u0441\u044f. \u042d\u0442\u043e \u043e\u0442\u043d\u043e\u0441\u0438\u0442\u0441\u044f \u043a \u0440\u0430\u0441\u043f\u0438\u0441\u0430\u043d\u0438\u044e, \u043a \u0434\u0435\u043d\u044c\u0433\u0430\u043c \u0438 \u043a \u043b\u044e\u0434\u044f\u043c. \u0420\u0435\u0437\u043a\u043e\u0441\u0442\u044c \u0441\u0435\u0433\u043e\u0434\u043d\u044f \u0432\u0441\u0451 \u043f\u043e\u0440\u0442\u0438\u0442; \u043c\u0435\u0434\u043b\u0435\u043d\u043d\u043e\u0435 \u0438 \u0440\u043e\u0432\u043d\u043e\u0435 \u2014 \u0432\u044b\u0438\u0433\u0440\u044b\u0432\u0430\u0435\u0442. \u0425\u043e\u0440\u043e\u0448\u0438\u0439 \u0434\u0435\u043d\u044c, \u0447\u0442\u043e\u0431\u044b \u0440\u0430\u0437\u0431\u0430\u0432\u0438\u0442\u044c: \u0440\u0430\u0431\u043e\u0442\u0443 \u2014 \u043f\u0440\u043e\u0433\u0443\u043b\u043a\u043e\u0439, \u0441\u043f\u043e\u0440 \u2014 \u043f\u0430\u0443\u0437\u043e\u0439, \u0434\u043b\u0438\u043d\u043d\u044b\u0439 \u0441\u043f\u0438\u0441\u043e\u043a \u2014 \u043e\u0434\u043d\u0438\u043c \u0432\u044b\u0447\u0435\u0440\u043a\u043d\u0443\u0442\u044b\u043c \u043f\u0443\u043d\u043a\u0442\u043e\u043c. \u041f\u0440\u043e\u043f\u043e\u0440\u0446\u0438\u044f \u0432\u0430\u0436\u043d\u0435\u0435 \u043e\u0431\u044a\u0451\u043c\u0430.","\u041a\u0440\u0430\u0439\u043d\u043e\u0441\u0442\u0438 \u0432\u044b\u0434\u0430\u044e\u0442 \u0441\u0435\u0431\u044f \u0437\u0430 \u0445\u0430\u0440\u0430\u043a\u0442\u0435\u0440. \u0412\u0441\u0451 \u0438\u043b\u0438 \u043d\u0438\u0447\u0435\u0433\u043e, \u0437\u0430\u043f\u043e\u0439 \u0440\u0430\u0431\u043e\u0442\u044b \u0438\u043b\u0438 \u043f\u043e\u043b\u043d\u043e\u0435 \u0431\u0435\u0437\u0434\u0435\u043b\u044c\u0435. \u0421\u0435\u0440\u0435\u0434\u0438\u043d\u0430 \u0441\u0435\u0433\u043e\u0434\u043d\u044f \u0441\u043a\u0443\u0447\u043d\u0430 \u0438 \u0438\u043c\u0435\u043d\u043d\u043e \u043f\u043e\u044d\u0442\u043e\u043c\u0443 \u043d\u0443\u0436\u043d\u0430.")
B.OI=new A.cs("15","\u0414\u044c\u044f\u0432\u043e\u043b","\u0426\u0435\u043f\u044c \u043d\u0435 \u0437\u0430\u043f\u0435\u0440\u0442\u0430","\u041f\u043e\u0441\u043c\u043e\u0442\u0440\u0438\u0442\u0435, \u0447\u0442\u043e \u0432\u0430\u0441 \u0434\u0435\u0440\u0436\u0438\u0442, \u0438 \u043f\u0440\u043e\u0432\u0435\u0440\u044c\u0442\u0435, \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0442\u0435\u043b\u044c\u043d\u043e \u043b\u0438 \u0434\u0435\u0440\u0436\u0438\u0442. \u041d\u0430 \u043a\u0430\u0440\u0442\u0435 \u0446\u0435\u043f\u0438 \u043d\u0430\u0434\u0435\u0442\u044b \u0441\u0432\u043e\u0431\u043e\u0434\u043d\u043e \u2014 \u0438\u0445 \u043c\u043e\u0436\u043d\u043e \u0441\u043d\u044f\u0442\u044c. \u0420\u0435\u0447\u044c \u043e \u043f\u0440\u0438\u0432\u044b\u0447\u043a\u0435, \u043e \u0434\u043e\u0433\u043e\u0432\u043e\u0440\u0451\u043d\u043d\u043e\u0441\u0442\u0438, \u043a\u043e\u0442\u043e\u0440\u0443\u044e \u0432\u044b \u0441\u043e\u0431\u043b\u044e\u0434\u0430\u0435\u0442\u0435 \u043f\u043e \u0438\u043d\u0435\u0440\u0446\u0438\u0438, \u043e \u0441\u0442\u0440\u0430\u0445\u0435, \u043a\u043e\u0442\u043e\u0440\u044b\u0439 \u0434\u0430\u0432\u043d\u043e \u043d\u0435 \u043f\u0440\u043e\u0432\u0435\u0440\u044f\u043b\u0441\u044f. \u0421\u0435\u0433\u043e\u0434\u043d\u044f \u0441\u0442\u043e\u0438\u0442 \u043d\u0430\u0437\u0432\u0430\u0442\u044c \u044d\u0442\u043e \u0441\u0432\u043e\u0438\u043c \u0438\u043c\u0435\u043d\u0435\u043c; \u043e\u0434\u043d\u043e\u0433\u043e \u043d\u0430\u0437\u0432\u0430\u043d\u0438\u044f \u0447\u0430\u0441\u0442\u043e \u0445\u0432\u0430\u0442\u0430\u0435\u0442. \u0418 \u043f\u0440\u043e\u0432\u0435\u0440\u044c\u0442\u0435, \u043d\u0435 \u0434\u0435\u0440\u0436\u0438\u0442\u0435 \u043b\u0438 \u0432\u044b \u043a\u043e\u0433\u043e-\u0442\u043e \u0441\u0430\u043c\u0438 \u2014 \u0438\u043d\u043e\u0433\u0434\u0430 \u0446\u0435\u043f\u044c \u0434\u0432\u0443\u0441\u0442\u043e\u0440\u043e\u043d\u043d\u044f\u044f, \u0438 \u0432\u0442\u043e\u0440\u0430\u044f \u0435\u0451 \u043f\u043e\u043b\u043e\u0432\u0438\u043d\u0430 \u0443 \u0432\u0430\u0441 \u0432 \u0440\u0443\u043a\u0435.","\u0426\u0435\u043f\u044c, \u043a\u043e\u0442\u043e\u0440\u0443\u044e \u0432\u0438\u0434\u043d\u043e, \u2014 \u0443\u0436\u0435 \u043d\u0430\u043f\u043e\u043b\u043e\u0432\u0438\u043d\u0443 \u0441\u043d\u044f\u0442\u0430. \u0421\u0435\u0433\u043e\u0434\u043d\u044f \u0445\u043e\u0440\u043e\u0448\u0438\u0439 \u0434\u0435\u043d\u044c \u0437\u0430\u043c\u0435\u0442\u0438\u0442\u044c, \u0447\u0442\u043e \u0432\u044b \u0434\u0435\u0440\u0436\u0438\u0442\u0435\u0441\u044c \u0437\u0430 \u0442\u043e, \u0447\u0442\u043e \u043d\u0430\u0437\u044b\u0432\u0430\u0435\u0442\u0435 \u043d\u0435\u043e\u0431\u0445\u043e\u0434\u0438\u043c\u043e\u0441\u0442\u044c\u044e: \u043f\u0440\u0438\u0432\u044b\u0447\u043a\u0443, \u0447\u0435\u043b\u043e\u0432\u0435\u043a\u0430, \u0440\u0430\u0431\u043e\u0442\u0443. \u0414\u0432\u0435\u0440\u044c \u043d\u0435 \u0437\u0430\u043f\u0435\u0440\u0442\u0430.")
B.OD=new A.cs("16","\u0411\u0430\u0448\u043d\u044f","\u0420\u0443\u0445\u043d\u0443\u043b\u043e \u2014 \u0438 \u0445\u043e\u0440\u043e\u0448\u043e","\u0427\u0442\u043e-\u0442\u043e \u0441\u0435\u0433\u043e\u0434\u043d\u044f \u0440\u0430\u0437\u0432\u0430\u043b\u0438\u0442\u0441\u044f, \u0438 \u044d\u0442\u043e \u0431\u0443\u0434\u0435\u0442 \u0442\u043e, \u0447\u0442\u043e \u0438 \u0442\u0430\u043a \u0441\u0442\u043e\u044f\u043b\u043e \u043a\u0440\u0438\u0432\u043e. \u041f\u0435\u0440\u0432\u043e\u0435 \u0447\u0443\u0432\u0441\u0442\u0432\u043e \u0431\u0443\u0434\u0435\u0442 \u043d\u0435\u043f\u0440\u0438\u044f\u0442\u043d\u044b\u043c, \u043d\u043e \u0447\u0435\u0440\u0435\u0437 \u043d\u0435\u0434\u0435\u043b\u044e \u043e\u043a\u0430\u0436\u0435\u0442\u0441\u044f, \u0447\u0442\u043e \u0432\u044b \u0438\u0437\u0431\u0430\u0432\u0438\u043b\u0438\u0441\u044c \u043e\u0442 \u043f\u043e\u0441\u0442\u0440\u043e\u0439\u043a\u0438, \u043a\u043e\u0442\u043e\u0440\u0443\u044e \u0441\u0430\u043c\u0438 \u0431\u043e\u044f\u043b\u0438\u0441\u044c \u0442\u0440\u043e\u0433\u0430\u0442\u044c. \u041d\u0435 \u043f\u044b\u0442\u0430\u0439\u0442\u0435\u0441\u044c \u0441\u0440\u043e\u0447\u043d\u043e \u0432\u043e\u0441\u0441\u0442\u0430\u043d\u043e\u0432\u0438\u0442\u044c \u043a\u0430\u043a \u0431\u044b\u043b\u043e. \u0420\u0430\u0437\u0431\u0435\u0440\u0438\u0442\u0435 \u043e\u0431\u043b\u043e\u043c\u043a\u0438 \u0438 \u043f\u043e\u0441\u043c\u043e\u0442\u0440\u0438\u0442\u0435, \u0447\u0442\u043e \u043e\u0441\u0442\u0430\u043b\u043e\u0441\u044c \u0446\u0435\u043b\u044b\u043c. \u0426\u0435\u043b\u044b\u043c \u043e\u0431\u044b\u0447\u043d\u043e \u043e\u043a\u0430\u0437\u044b\u0432\u0430\u0435\u0442\u0441\u044f \u0431\u043e\u043b\u044c\u0448\u0435, \u0447\u0435\u043c \u043e\u0436\u0438\u0434\u0430\u043b\u043e\u0441\u044c. \u0421\u0447\u0438\u0442\u0430\u0439\u0442\u0435 \u043f\u043e\u0441\u043b\u0435 \u0442\u043e\u0433\u043e, \u043a\u0430\u043a \u043e\u0441\u044f\u0434\u0435\u0442 \u043f\u044b\u043b\u044c, \u0430 \u043d\u0435 \u0432\u043e \u0432\u0440\u0435\u043c\u044f.","\u041e\u0431\u0432\u0430\u043b, \u043a\u043e\u0442\u043e\u0440\u044b\u0439 \u0432\u044b \u043e\u0442\u043a\u043b\u0430\u0434\u044b\u0432\u0430\u0435\u0442\u0435. \u0422\u0440\u0435\u0449\u0438\u043d\u0430 \u0435\u0441\u0442\u044c, \u0432\u044b \u0435\u0451 \u0432\u0438\u0434\u0438\u0442\u0435 \u0438 \u043f\u043e\u0434\u043a\u043b\u0435\u0438\u0432\u0430\u0435\u0442\u0435. \u0420\u0430\u0437\u043e\u0431\u0440\u0430\u0442\u044c \u0441\u0430\u043c\u043e\u043c\u0443 \u0434\u0435\u0448\u0435\u0432\u043b\u0435, \u0447\u0435\u043c \u0436\u0434\u0430\u0442\u044c, \u043f\u043e\u043a\u0430 \u0440\u0443\u0445\u043d\u0435\u0442 \u0432 \u043d\u0435\u0443\u0434\u043e\u0431\u043d\u044b\u0439 \u043c\u043e\u043c\u0435\u043d\u0442.")
B.OC=new A.cs("17","\u0417\u0432\u0435\u0437\u0434\u0430","\u041f\u0435\u0440\u0435\u0434\u044b\u0448\u043a\u0430 \u043f\u043e\u0441\u043b\u0435 \u0442\u0440\u0443\u0434\u043d\u043e\u0433\u043e","\u041f\u043e\u0441\u043b\u0435 \u0442\u044f\u0436\u0451\u043b\u043e\u0433\u043e \u043f\u0440\u0438\u0445\u043e\u0434\u0438\u0442 \u0442\u0438\u0445\u043e\u0435. \u0421\u0435\u0433\u043e\u0434\u043d\u044f \u043c\u043e\u0436\u043d\u043e \u0432\u044b\u0434\u043e\u0445\u043d\u0443\u0442\u044c: \u0445\u0443\u0434\u0448\u0435\u0435 \u043f\u043e\u0437\u0430\u0434\u0438, \u0434\u0430\u0436\u0435 \u0435\u0441\u043b\u0438 \u0435\u0449\u0451 \u043d\u0435 \u0432\u0435\u0440\u0438\u0442\u0441\u044f. \u0417\u0432\u0435\u0437\u0434\u0430 \u043b\u044c\u0451\u0442 \u0432\u043e\u0434\u0443 \u0438 \u043d\u0430 \u0437\u0435\u043c\u043b\u044e, \u0438 \u0432 \u0438\u0441\u0442\u043e\u0447\u043d\u0438\u043a \u2014 \u0442\u043e \u0435\u0441\u0442\u044c \u043e\u0442\u0434\u0430\u0451\u0442 \u0438 \u0432\u043e\u0441\u043f\u043e\u043b\u043d\u044f\u0435\u0442 \u043e\u0434\u043d\u043e\u0432\u0440\u0435\u043c\u0435\u043d\u043d\u043e. \u0425\u043e\u0440\u043e\u0448\u0438\u0439 \u0434\u0435\u043d\u044c, \u0447\u0442\u043e\u0431\u044b \u0432\u0435\u0440\u043d\u0443\u0442\u044c\u0441\u044f \u043a \u0442\u043e\u043c\u0443, \u0447\u0442\u043e \u0432\u044b \u043b\u044e\u0431\u0438\u0442\u0435 \u0438 \u0437\u0430\u0431\u0440\u043e\u0441\u0438\u043b\u0438. \u0418 \u0447\u0442\u043e\u0431\u044b \u043d\u0430\u0434\u0435\u044f\u0442\u044c\u0441\u044f \u0432\u0441\u043b\u0443\u0445. \u041d\u0435 \u0442\u0440\u0435\u0431\u0443\u0439\u0442\u0435 \u043e\u0442 \u0441\u0435\u0431\u044f \u0441\u0435\u0433\u043e\u0434\u043d\u044f \u043c\u043d\u043e\u0433\u043e\u0433\u043e. \u0412\u043e\u0441\u0441\u0442\u0430\u043d\u043e\u0432\u043b\u0435\u043d\u0438\u0435 \u2014 \u044d\u0442\u043e \u0442\u043e\u0436\u0435 \u0440\u0430\u0431\u043e\u0442\u0430, \u0438 \u043e\u043d\u0430 \u0438\u0434\u0451\u0442, \u0434\u0430\u0436\u0435 \u043a\u043e\u0433\u0434\u0430 \u0441\u043d\u0430\u0440\u0443\u0436\u0438 \u043d\u0438\u0447\u0435\u0433\u043e \u043d\u0435 \u043f\u0440\u043e\u0438\u0441\u0445\u043e\u0434\u0438\u0442.","\u041d\u0430\u0434\u0435\u0436\u0434\u0430 \u0441\u0442\u0430\u043b\u0430 \u043c\u0435\u0447\u0442\u0430\u043d\u0438\u0435\u043c. \u0421\u043c\u043e\u0442\u0440\u0435\u0442\u044c \u043d\u0430 \u0437\u0432\u0435\u0437\u0434\u0443 \u043f\u0440\u0438\u044f\u0442\u043d\u043e \u0438 \u043d\u0438 \u043a \u0447\u0435\u043c\u0443 \u043d\u0435 \u043e\u0431\u044f\u0437\u044b\u0432\u0430\u0435\u0442. \u041b\u0438\u0431\u043e \u0432\u044b \u043f\u0435\u0440\u0435\u0441\u0442\u0430\u043b\u0438 \u0432\u0435\u0440\u0438\u0442\u044c \u0441\u043e\u0432\u0441\u0435\u043c \u0438 \u043d\u0430\u0437\u044b\u0432\u0430\u0435\u0442\u0435 \u044d\u0442\u043e \u0440\u0435\u0430\u043b\u0438\u0437\u043c\u043e\u043c.")
